helpers.log('Starting Send Email node');

const smtpServer = node.properties.smtpServer.value;
const smtpPort = node.properties.smtpPort.value;
const username = node.properties.username.value;
const password = node.properties.password.value;
const recipientsConfig = node.properties.recipients?.value || [];
const subject = node.properties.subject.value;
const body = node.properties.body.value;
const attachmentsConfig = node.properties.attachments?.value || [];

helpers.log(`SMTP: ${smtpServer}:${smtpPort}`);

// Process recipients
const toRecipients = [];
const ccRecipients = [];
const bccRecipients = [];

if (Array.isArray(recipientsConfig) && recipientsConfig.length > 0) {
  helpers.log(`Processing ${recipientsConfig.length} recipient(s)`);
  for (const recipient of recipientsConfig) {
    const email = recipient.email;
    const type = recipient.type || 'to';

    if (!email) continue;

    switch (type) {
      case 'to':
        toRecipients.push(email);
        break;
      case 'cc':
        ccRecipients.push(email);
        break;
      case 'bcc':
        bccRecipients.push(email);
        break;
    }
  }

  helpers.log(`To: ${toRecipients.length}, CC: ${ccRecipients.length}, BCC: ${bccRecipients.length}`);
} else {
  helpers.warn('No recipients configured');
}

// Process attachments
const attachments = [];
if (Array.isArray(attachmentsConfig) && attachmentsConfig.length > 0) {
  helpers.log(`Processing ${attachmentsConfig.length} attachment(s)`);
  for (const attachment of attachmentsConfig) {
    if (!attachment.filename || !attachment.content) {
      helpers.warn('Skipping attachment with missing filename or content');
      continue;
    }

    attachments.push({
      filename: attachment.filename,
      content: attachment.content,
      contentType: attachment.contentType || 'application/octet-stream'
    });

    helpers.log(`Attachment: ${attachment.filename} (${attachment.contentType || 'default'})`);
  }
}

// Validate required fields
if (toRecipients.length === 0) {
  helpers.error('No To recipients specified');
  return {
    error: 'At least one To recipient is required'
  };
}

if (!subject) {
  helpers.warn('Email has no subject');
}

try {
  // Note: This requires nodemailer to be installed
  // npm install nodemailer

  const nodemailer = await import('nodemailer');

  helpers.log('Creating SMTP transporter...');
  const transporter = nodemailer.default.createTransport({
    host: smtpServer,
    port: smtpPort,
    auth: {
      user: username,
      pass: password
    }
  });

  helpers.log('Sending email...');
  const mailOptions = {
    from: username,
    to: toRecipients.join(', '),
    subject: subject,
    html: body
  };

  if (ccRecipients.length > 0) {
    mailOptions.cc = ccRecipients.join(', ');
  }

  if (bccRecipients.length > 0) {
    mailOptions.bcc = bccRecipients.join(', ');
  }

  if (attachments.length > 0) {
    mailOptions.attachments = attachments;
  }

  const info = await transporter.sendMail(mailOptions);

  helpers.log(`Email sent successfully: ${info.messageId}`);

  return {
    success: true,
    messageId: info.messageId,
    to: toRecipients,
    cc: ccRecipients,
    bcc: bccRecipients,
    attachmentCount: attachments.length,
    subject
  };

} catch (error) {
  helpers.error('Failed to send email:', error.message);
  return {
    error: error.message,
    details: error.stack,
    note: 'Make sure nodemailer is installed: npm install nodemailer'
  };
}
